import{z as i,x as m,o as r,c as A,q as c,j as n,D as t,d as l,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"jemalloc / tcmalloc 竞技场","description":"","frontmatter":{"title":"jemalloc / tcmalloc 竞技场","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arena-allocators.md","filePath":"cs/arena-allocators.md","lastUpdated":1791063341000}'),p={name:"cs/arena-allocators.md"};function B(d,a,h,S,u,f){const o=m("Mermaid");return r(),A("div",null,[a[2]||(a[2]=c('<h1 id="jemalloc-tcmalloc-竞技场" tabindex="-1">jemalloc / tcmalloc 竞技场 <a class="header-anchor" href="#jemalloc-tcmalloc-竞技场" aria-label="Permalink to &quot;jemalloc / tcmalloc 竞技场&quot;">​</a></h1><div class="epigraph"><p>竞技场让每线程或每核几乎不共享空闲链：分配本地化，减少 malloc 锁，碎片在 arena 之间可能上升。</p><footer>—— 据 Evans, jemalloc 论文与手册；Google tcmalloc 设计文档</footer></div><p><a href="/cs/malloc-implementation">上一课</a>的单 arena 在多核上抢一把堆锁。缺口是 <strong>jemalloc/tcmalloc 的 arena/tcache</strong>：仍是用户态，不是内核 percpu。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>glibc 后来也有 per-thread 缓存，但历史上争用严重。jemalloc：多个 arena，线程绑定一个，size class extents。tcmalloc：per-thread cache + 中央页堆。缺口：fork 后子进程继承缓存要清；<a href="/cs/memcg">memcg</a> 看见的是 RSS，不管 arena 内部空闲；与 <a href="/cs/numa-mempolicy">NUMA</a> 可每节点 arena。本课不把两个库的调参字典抄完。</p><p><span class="marginnote">数字实例：单堆一把锁时，8 个高频分配线程可能一小半周期耗在排队等锁；切成 8 个 arena 后各用各的锁，几乎不再相遇。tcache 更进一步：多数分配释放在线程本地完成，连 arena 的锁都不用碰——争用被摊薄到偶尔的「补货」上。</span></p><p><span class="marginnote">extent 在 jemalloc 里是连续虚存管理，类似内核的 vma 但在用户。tcmalloc 的 span 同类。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线程首次 malloc：选 arena，填 tcache。释放：先回 tcache，溢出灌回 arena。对照内核 <a href="/cs/slab-allocator">slab</a> 的 per-cpu 杂志。对照 <a href="/cs/rss-multiqueue">RSS 网卡</a>：都是为了少跨核。对照 KSM：tcache 里的空闲不一定是零页。</p><p><span class="marginnote">术语翻译：tcache（线程缓存）就是每个线程手边的零钱盒——常用尺寸（32、64 字节这类）各存一小叠，分配直接拿、释放先放回；空了或满了才去 arena 这家「银行」整批取还，把昂贵的跨线程同步摊薄成偶发大额交易。</span></p>',10)),(r(),n(E,null,{default:t(()=>[s(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E7%BA%BF%E7%A8%8B0%20tcache%22%5D%20--%3E%20A0%5B%22arena%200%22%5D%0A%20%20T1%5B%22%E7%BA%BF%E7%A8%8B1%20tcache%22%5D%20--%3E%20A1%5B%22arena%201%22%5D%0A%20%20A0%20--%3E%20MM%5B%22mmap%20%E5%90%91%E5%86%85%E6%A0%B8%22%5D%0A%20%20A1%20--%3E%20MM%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"竞技场用空间换时间：每 arena 自留空闲，RSS 可能比单堆大，但吞吐高。这是服务端默认换 glibc 的原因之一。不要写成 JVM GC 课。与 MTE：每个 arena 的释放仍要换标签。",-1)),a[5]||(a[5]=e("p",null,"调试：工具要懂 tcache，否则「free 了仍 RSS 高」是预期。",-1)),a[6]||(a[6]=e("p",null,[l("实现上：extent 保留虚址但不一定立刻要物理页，RSS 与 VSS 差一截。per-node arena 减少跨 NUMA 原子操作。后台 purge 线程才把空闲还内核。 读法上只引用"),e("a",{href:"/cs/malloc-implementation"},"上一课"),l("的结论，不把对象换成训练推理或限价簿。")],-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者看到「free 了 RSS 却不降」就断定内存泄漏。arena 本就保留虚址复用：RSS 高不等于内存丢了，只有后台 purge 线程把 extent 归还内核才会降——监控与排障工具必须懂 tcache，否则误报满屏。")],-1)),(r(),n(E,null,{default:t(()=>[s(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREE%5B%22%E7%BA%BF%E7%A8%8B%E8%B0%83%20free%22%5D%20--%3E%20TC%5B%22%E5%85%88%E5%BD%92%E8%BF%98%E7%BA%BF%E7%A8%8B%E6%9C%AC%E5%9C%B0%20tcache%22%5D%0A%20%20TC%20--%3E%20FULL%7B%22tcache%20%E5%B7%B2%E6%BB%A1%3F%22%7D%0A%20%20FULL%20--%3E%7C%E5%90%A6%7C%20STAY%5B%22%E7%95%99%E5%9C%A8%20tcache%3A%20RSS%20%E4%B8%8D%E5%8F%98%22%5D%0A%20%20FULL%20--%3E%7C%E6%98%AF%7C%20AR%5B%22%E6%89%B9%E9%87%8F%E7%81%8C%E5%9B%9E%20arena%20%E7%9A%84%20extent%20%E7%A9%BA%E9%97%B2%E8%A1%A8%22%5D%0A%20%20AR%20--%3E%20PURGE%7B%22%E5%90%8E%E5%8F%B0%20purge%20%E7%BA%BF%E7%A8%8B%E6%98%AF%E5%90%A6%E8%BF%90%E8%A1%8C%3F%22%7D%0A%20%20PURGE%20--%3E%7C%E6%9C%AA%E8%BF%90%E8%A1%8C%7C%20HOLD%5B%22%E8%99%9A%E5%9D%80%E4%BB%8D%E8%87%AA%E7%95%99%3A%20RSS%20%E4%BB%8D%E4%B8%8D%E9%99%8D%22%5D%0A%20%20PURGE%20--%3E%7C%E8%BF%90%E8%A1%8C%7C%20RET%5B%22madvise%20%E5%BD%92%E8%BF%98%E5%86%85%E6%A0%B8%3A%20RSS%20%E6%89%8D%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=c('<p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>jemalloc / tcmalloc 竞技场</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 mimalloc/snmalloc 的全部对照。不保证实时无锁分配器的最坏边界。内存进阶收口于检测工具：ASan 如何用影子内存。</p><p>版本字段会变，课序钉的是机制对象「jemalloc / tcmalloc 竞技场」，不是某一主线内核的结构体名。 后课默认：多线程堆用 arena/tcache 减锁。AddressSanitizer 的影子与红区，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>jemalloc/tcmalloc 用多 arena 与线程缓存减锁。</li><li>RSS 可能因空闲保留而更高。</li><li>ASan 机制是下一课。</li><li>出处：Evans jemalloc；tcmalloc 设计；Wilson 分配综述。</li></ul>',7))])}const T=i(p,[["render",B]]);export{C as __pageData,T as default};
